SELECT p.id, p.symbol, (SELECT CONCAT(q.id,'|',q.close_reason,'|',q.realized_pnl,'|',q.closed_at) FROM crypto_ai.paper_position q WHERE q.symbol=p.symbol AND q.id<>p.id AND q.closed_at<=p.opened_at ORDER BY q.closed_at DESC LIMIT 1) AS prev_same_symbol, TIMESTAMPDIFF(SECOND,(SELECT MAX(q.closed_at) FROM crypto_ai.paper_position q WHERE q.symbol=p.symbol AND q.id<>p.id AND q.closed_at<=p.opened_at), p.opened_at) AS gap_since_prev_exit_s FROM crypto_ai.paper_position p WHERE p.id IN (182,172,162,158,143,137) ORDER BY p.id;